INSERT INTO `protocol_templates` VALUES (1,1,'Default AmneziaWG','[Interface]\nPrivateKey = {{private_key}}\nAddress = {{client_ip}}/32\nDNS = 8.8.8.8, 8.8.4.4\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nEndpoint = {{server_host}}:{{server_port}}\nAllowedIPs = 0.0.0.0/0\nPersistentKeepalive = 25\n\nJc = {{jc}}\nJmin = {{jmin}}\nJmax = {{jmax}}\nS1 = {{s1}}\nS2 = {{s2}}\nH1 = {{h1}}\nH2 = {{h2}}\nH3 = {{h3}}\nH4 = {{h4}}',1,'2026-10-12 13:06:53'),(2,2,'Default WireGuard','[Interface]\nPrivateKey = {{private_key}}\nAddress = {{client_ip}}/32\nDNS = 8.8.8.8, 8.8.4.4\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nEndpoint = {{server_host}}:{{server_port}}\nAllowedIPs = 0.0.0.0/0\nPersistentKeepalive = 25',1,'2026-10-12 13:06:53'),(3,3,'Default OpenVPN','client\ndev tun\nproto {{protocol}}\nremote {{server_host}} {{server_port}}\nresolv-retry infinite\nnobind\npersist-key\npersist-tun\nca ca.crt\ncert client.crt\nkey client.key\nremote-cert-tls server\ncipher AES-256-GCM\nauth SHA256\nverb 3',1,'2026-10-12 13:06:53'),(4,4,'Default Shadowsocks','{\n  \"server\": \"{{server_host}}\",\n  \"server_port\": {{server_port}},\n  \"password\": \"{{password}}\",\n  \"method\": \"{{method}}\"\n}',1,'2026-10-12 13:06:53'),(5,11,'Default AmneziaWG','[Interface]\nPrivateKey = {{private_key}}\nAddress = {{client_ip}}/32\nDNS = 8.8.8.8, 8.8.4.4\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nEndpoint = {{server_host}}:{{server_port}}\nAllowedIPs = 0.0.0.0/0\nPersistentKeepalive = 25\n\nJc = {{jc}}\nJmin = {{jmin}}\nJmax = {{jmax}}\nS1 = {{s1}}\nS2 = {{s2}}\nH1 = {{h1}}\nH2 = {{h2}}\nH3 = {{h3}}\nH4 = {{h4}}',1,'2026-10-12 13:07:15'),(6,12,'Default MTProxy','tg://proxy?server={{server_host}}&port={{server_port}}&secret={{secret}}',1,'2026-10-12 13:07:16'),(7,13,'Default AIVPN','aivpn://{{connection_key}}',1,'2026-10-12 13:07:18'),(8,14,'Default WARP','WARP SOCKS5 Proxy: socks5h://127.0.0.1:{{warp_proxy_port}}\nWARP IP: {{warp_ip}}\nMode: {{warp_mode}}\nServer: {{server_host}}',1,'2026-10-12 13:07:23'),(9,15,'Default AmneziaWG 3.1','[Interface]\nAddress = {{client_ip}}/32\nDNS = {{dns_servers}}\nPrivateKey = {{private_key}}\nJc = {{Jc}}\nJmin = {{Jmin}}\nJmax = {{Jmax}}\nS1 = {{S1}}\nS2 = {{S2}}\nS3 = {{S3}}\nS4 = {{S4}}\nH1 = {{H1}}\nH2 = {{H2}}\nH3 = {{H3}}\nH4 = {{H4}}\nI1 = {{I1}}\nI2 = {{I2}}\nI3 = {{I3}}\nI4 = {{I4}}\nI5 = {{I5}}\nHeaderProtectionKey = {{HeaderProtectionKey}}\nContentPaddingAddition = {{ContentPaddingAddition}}\nRekeyAfterTime = {{RekeyAfterTime}}\nRekeyTimeout = {{RekeyTimeout}}\nRejectAfterTime = {{RejectAfterTime}}\nKeepaliveTimeout = {{KeepaliveTimeout}}\nMaxHandshakeAttempts = {{MaxHandshakeAttempts}}\nRandomTrailers = {{RandomTrailers}}\nDisableCookies = {{DisableCookies}}\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nAllowedIPs = 0.0.0.0/0, ::/0\nEndpoint = {{server_host}}:{{server_port}}\nPersistentKeepalive = 25-35',1,'2026-10-12 13:07:25');
