  `uninstall_script` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `password_command` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `output_template` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ubuntu_compatible` tinyint(1) DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `qr_code_template` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
