INSERT INTO `protocols` VALUES (1,'AmneziaWG Advanced','amnezia-wg-advanced','AmneziaWG protocol with advanced junk packet obfuscation parameters',NULL,'#!/bin/bash\nset -euo pipefail\n\nCONTAINER_NAME=\"${CONTAINER_NAME:-amnezia-awg}\"\nPORT_RANGE_START=${PORT_RANGE_START:-30000}\nPORT_RANGE_END=${PORT_RANGE_END:-65000}\nVPN_PORT=${VPN_PORT:-$((RANDOM % (PORT_RANGE_END - PORT_RANGE_START + 1) + PORT_RANGE_START))}\nMTU=${MTU:-1420}\n\nmkdir -p /opt/amnezia/awg\n\n# Check if container exists and is running\ncontainer_running() {\n  docker inspect --format=\"{{.State.Running}}\" \"$CONTAINER_NAME\" 2>/dev/null | grep -q true\n}\n\n# Clean up broken configs\nif [ -f /opt/amnezia/awg/wg0.conf ]; then\n  if grep -q \"PRIVATE_KEY\" /opt/amnezia/awg/wg0.conf 2>/dev/null; then\n    rm -f /opt/amnezia/awg/wg0.conf\n  fi\n  if grep -Eiq \"^S3[[:space:]]*=\" /opt/amnezia/awg/wg0.conf 2>/dev/null; then\n    rm -f /opt/amnezia/awg/wg0.conf\n  fi\n  if grep -Eiq \"^H[1-4][[:space:]]*=[[:space:]]*0x\" /opt/amnezia/awg/wg0.conf 2>/dev/null; then\n    rm -f /opt/amnezia/awg/wg0.conf\n  fi\n  if grep -Eiq \"^H1[[:space:]]*=[[:space:]]*1$\" /opt/amnezia/awg/wg0.conf 2>/dev/null; then\n    rm -f /opt/amnezia/awg/wg0.conf\n  fi\nfi\n\n# If valid config exists, just ensure container is running\nif [ -f /opt/amnezia/awg/wg0.conf ]; then\n  echo \"Found existing configuration\"\n  VPN_PORT=$(grep -E \"^ListenPort\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \" || echo \"$VPN_PORT\")\n  \n  if ! container_running; then\n    docker rm -f \"$CONTAINER_NAME\" 2>/dev/null || true\n    docker run -d --name \"$CONTAINER_NAME\" --restart always --privileged --cap-add=NET_ADMIN --cap-add=SYS_MODULE -p \"${VPN_PORT}:${VPN_PORT}/udp\" -v /lib/modules:/lib/modules -v /opt/amnezia/awg:/opt/amnezia/awg amneziavpn/amnezia-wg:latest sh -c \"wg-quick up /opt/amnezia/awg/wg0.conf && sleep infinity\"\n    sleep 3\n    # Force reload interface to apply AWG params\n    docker exec \"$CONTAINER_NAME\" ip link del wg0 2>/dev/null || true\n    docker exec \"$CONTAINER_NAME\" wg-quick up /opt/amnezia/awg/wg0.conf\n  fi\n  \n  PUBKEY=$(cat /opt/amnezia/awg/wireguard_server_public_key.key 2>/dev/null || echo \"\")\n  PSK=$(cat /opt/amnezia/awg/wireguard_psk.key 2>/dev/null || echo \"\")\n  JC=$(grep -E \"^Jc\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  JMIN=$(grep -E \"^Jmin\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  JMAX=$(grep -E \"^Jmax\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  S1=$(grep -E \"^S1\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  S2=$(grep -E \"^S2\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  H1=$(grep -E \"^H1\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  H2=$(grep -E \"^H2\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  H3=$(grep -E \"^H3\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  H4=$(grep -E \"^H4\" /opt/amnezia/awg/wg0.conf | cut -d= -f2 | tr -d \" \")\n  \n  echo \"Using existing AmneziaWG configuration\"\n  echo \"Variable: server_port=$VPN_PORT\"\n  echo \"Variable: server_public_key=$PUBKEY\"\n  echo \"Variable: preshared_key=$PSK\"\n  echo \"Variable: container_name=$CONTAINER_NAME\"\n  echo \"Variable: Jc=$JC\"\n  echo \"Variable: Jmin=$JMIN\"\n  echo \"Variable: Jmax=$JMAX\"\n  echo \"Variable: S1=$S1\"\n  echo \"Variable: S2=$S2\"\n  echo \"Variable: H1=$H1\"\n  echo \"Variable: H2=$H2\"\n  echo \"Variable: H3=$H3\"\n  echo \"Variable: H4=$H4\"\n  exit 0\nfi\n\n# FRESH INSTALL\necho \"Starting fresh AmneziaWG Advanced installation...\"\n\n# Remove old container if exists\ndocker rm -f \"$CONTAINER_NAME\" 2>/dev/null || true\n\n# Start container FIRST so we can use wg tools inside it\ndocker run -d --name \"$CONTAINER_NAME\" --restart always --privileged --cap-add=NET_ADMIN --cap-add=SYS_MODULE -p \"${VPN_PORT}:${VPN_PORT}/udp\" -v /lib/modules:/lib/modules -v /opt/amnezia/awg:/opt/amnezia/awg amneziavpn/amnezia-wg:latest sh -c \"while [ ! -f /opt/amnezia/awg/wg0.conf ]; do sleep 1; done; wg-quick up /opt/amnezia/awg/wg0.conf && sleep infinity\"\nsleep 3\n\n# Generate keys using the container\nPRIVATE_KEY=$(docker exec \"$CONTAINER_NAME\" wg genkey)\nPUBLIC_KEY=$(echo \"$PRIVATE_KEY\" | docker exec -i \"$CONTAINER_NAME\" wg pubkey)\nPRESHARED_KEY=$(docker exec \"$CONTAINER_NAME\" wg genpsk)\n\n# Generate random obfuscation parameters\nJC=$((RANDOM % 8 + 3))\nJMIN=50\nJMAX=$((RANDOM % 500 + 500))\nS1=$((RANDOM % 150 + 50))\nS2=$((RANDOM % 150 + 50))\nH1=$(od -vAn -N4 -tu4 < /dev/urandom | tr -d \" \")\nH2=$(od -vAn -N4 -tu4 < /dev/urandom | tr -d \" \")\nH3=$(od -vAn -N4 -tu4 < /dev/urandom | tr -d \" \")\nH4=$(od -vAn -N4 -tu4 < /dev/urandom | tr -d \" \")\n\n# Create config file\ncat > /opt/amnezia/awg/wg0.conf << WGCONF\n[Interface]\nPrivateKey = $PRIVATE_KEY\nAddress = 10.8.1.1/24\nListenPort = $VPN_PORT\nMTU = $MTU\nJc = $JC\nJmin = $JMIN\nJmax = $JMAX\nS1 = $S1\nS2 = $S2\nH1 = $H1\nH2 = $H2\nH3 = $H3\nH4 = $H4\nPostUp = iptables -A FORWARD -i %i -j ACCEPT; iptables -A FORWARD -o %i -j ACCEPT; iptables -t nat -A POSTROUTING -o eth0 -j MASQUERADE\nPostDown = iptables -D FORWARD -i %i -j ACCEPT; iptables -D FORWARD -o %i -j ACCEPT; iptables -t nat -D POSTROUTING -o eth0 -j MASQUERADE\nWGCONF\n\n# Save keys\necho \"$PRIVATE_KEY\" > /opt/amnezia/awg/wireguard_server_private_key.key\necho \"$PUBLIC_KEY\" > /opt/amnezia/awg/wireguard_server_public_key.key\necho \"$PRESHARED_KEY\" > /opt/amnezia/awg/wireguard_psk.key\necho \"[]\" > /opt/amnezia/awg/clientsTable\n\n# Restart container and explicitly reload WG interface to apply AWG params\ndocker restart \"$CONTAINER_NAME\"\nsleep 2\n\n# CRITICAL: Force reload interface to apply AWG obfuscation parameters\ndocker exec \"$CONTAINER_NAME\" ip link del wg0 2>/dev/null || true\ndocker exec \"$CONTAINER_NAME\" wg-quick up /opt/amnezia/awg/wg0.conf\nsleep 1\n\necho \"AmneziaWG Advanced installed successfully\"\necho \"Variable: server_port=$VPN_PORT\"\necho \"Variable: server_public_key=$PUBLIC_KEY\"\necho \"Variable: preshared_key=$PRESHARED_KEY\"\necho \"Variable: container_name=$CONTAINER_NAME\"\necho \"Variable: Jc=$JC\"\necho \"Variable: Jmin=$JMIN\"\necho \"Variable: Jmax=$JMAX\"\necho \"Variable: S1=$S1\"\necho \"Variable: S2=$S2\"\necho \"Variable: H1=$H1\"\necho \"Variable: H2=$H2\"\necho \"Variable: H3=$H3\"\necho \"Variable: H4=$H4\"\n','#!/bin/bash\nset -euo pipefail\n\nCONTAINER_NAME=\"${CONTAINER_NAME:-amnezia-awg}\"\n\ndocker stop \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker rm -fv \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker image rm amneziavpn/amnezia-wg:latest 2>/dev/null || true\ndocker network rm amnezia-dns-net 2>/dev/null || true\nrm -rf /opt/amnezia/amnezia-awg 2>/dev/null || true\nrm -rf /opt/amnezia/awg 2>/dev/null || true\n\necho \"{\"success\":true,\"message\":\"AmneziaWG uninstalled\"}\"',NULL,'[Interface]\nPrivateKey = {{private_key}}\nAddress = {{client_ip}}/32\nDNS = {{dns_servers}}\nMTU = 1280\nJc = {{Jc}}\nJmin = {{Jmin}}\nJmax = {{Jmax}}\nS1 = {{S1}}\nS2 = {{S2}}\nH1 = {{H1}}\nH2 = {{H2}}\nH3 = {{H3}}\nH4 = {{H4}}\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nAllowedIPs = 0.0.0.0/0, ::/0\nEndpoint = {{server_host}}:{{server_port}}\nPersistentKeepalive = 25',1,1,'2026-10-12 13:06:53','2026-10-13 06:32:06','{\n    \"containers\": [\n        {\n            \"awg\": {\n                \"H1\": \"{{H1}}\",\n                \"H2\": \"{{H2}}\",\n                \"H3\": \"{{H3}}\",\n                \"H4\": \"{{H4}}\",\n                \"Jc\": \"{{Jc}}\",\n                \"Jmax\": \"{{Jmax}}\",\n                \"Jmin\": \"{{Jmin}}\",\n                \"S1\": \"{{S1}}\",\n                \"S2\": \"{{S2}}\",\n                \"last_config\": {{last_config_json}},\n                \"port\": \"{{port}}\",\n                \"transport_proto\": \"udp\"\n            },\n            \"container\": \"amnezia-awg\"\n        }\n    ],\n    \"defaultContainer\": \"amnezia-awg\",\n    \"description\": \"{{description}}\",\n    \"dns1\": \"{{dns1}}\",\n    \"dns2\": \"{{dns2}}\",\n    \"hostName\": \"{{hostName}}\"\n}','amnezia_compressed',0),(2,'WireGuard Standard','wireguard-standard','Standard WireGuard VPN protocol',NULL,'#!/bin/bash\nCONTAINER_NAME=\"wireguard\"\nVPN_SUBNET=\"10.8.2.0/24\"\nPRIVATE_KEY=$(wg genkey)\nPUBLIC_KEY=$(echo $PRIVATE_KEY | wg pubkey)\nPRESHARED_KEY=$(wg genpsk)\ndocker run -d \n  --name $CONTAINER_NAME \n  --cap-add=NET_ADMIN \n  --cap-add=SYS_MODULE \n  -v /opt/wireguard:/etc/wireguard \n  linuxserver/wireguard\ncat > /opt/wireguard/wg0.conf << EOF\n[Interface]\nPrivateKey = $PRIVATE_KEY\nAddress = 10.8.2.1/24\nListenPort = 51820\n\n[Peer]\nPublicKey = \nPresharedKey = $PRESHARED_KEY\nAllowedIPs = 10.8.2.2/32\nEOF\necho \"WireGuard Standard installed successfully\"\necho \"Server Public Key: $PUBLIC_KEY\"',NULL,NULL,'[Interface]\nPrivateKey = {{private_key}}\nAddress = {{client_ip}}/32\nDNS = 8.8.8.8, 8.8.4.4\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nEndpoint = {{server_host}}:{{server_port}}\nAllowedIPs = 0.0.0.0/0\nPersistentKeepalive = 25',1,0,'2026-10-12 13:06:53','2026-10-12 13:07:15',NULL,'amnezia_compressed',0),(3,'OpenVPN','openvpn','OpenVPN protocol with TCP/UDP support',NULL,'#!/bin/bash\nCONTAINER_NAME=\"openvpn\"\nVPN_SUBNET=\"10.8.3.0/24\"\ndocker run -d \n  --name $CONTAINER_NAME \n  --cap-add=NET_ADMIN \n  -p 1194:1194/udp \n  -p 1194:1194/tcp \n  -v /opt/openvpn:/etc/openvpn \n  kylemanna/openvpn\ndocker exec -it $CONTAINER_NAME ovpn_genconfig -u udp://{{server_host}}:1194\ndocker exec -it $CONTAINER_NAME ovpn_initpki\necho \"OpenVPN installed successfully\"\necho \"Available on ports: 1194/udp, 1194/tcp\"',NULL,NULL,'client\ndev tun\nproto {{protocol}}\nremote {{server_host}} {{server_port}}\nresolv-retry infinite\nnobind\npersist-key\npersist-tun\nca ca.crt\ncert client.crt\nkey client.key\nremote-cert-tls server\ncipher AES-256-GCM\nauth SHA256\nverb 3',1,0,'2026-10-12 13:06:53','2026-10-12 13:07:15',NULL,'amnezia_compressed',0),(4,'Shadowsocks','shadowsocks','Shadowsocks proxy protocol',NULL,'#!/bin/bash\nCONTAINER_NAME=\"shadowsocks\"\nPASSWORD=$(openssl rand -base64 12)\ndocker run -d \n  --name $CONTAINER_NAME \n  -p 8388:8388 \n  -e METHOD=aes-256-gcm \n  -e PASSWORD=$PASSWORD \n  shadowsocks/shadowsocks-libev\necho \"Shadowsocks installed successfully\"\necho \"Port: 8388\"\necho \"Method: aes-256-gcm\"\necho \"Password: $PASSWORD\"',NULL,NULL,'{\n  \"server\": \"{{server_host}}\",\n  \"server_port\": {{server_port}},\n  \"password\": \"{{password}}\",\n  \"method\": \"{{method}}\"\n}',1,0,'2026-10-12 13:06:53','2026-10-12 13:07:15',NULL,'amnezia_compressed',0),(5,'SMB Server','smb','Samba SMB file share inside Docker with random host port',NULL,'#!/bin/bash\n\nset -euo pipefail\nset -x\n\nCONTAINER_NAME=\"${CONTAINER_NAME:-amnezia-smb}\"\nPORT_RANGE_START=${PORT_RANGE_START:-30000}\nPORT_RANGE_END=${PORT_RANGE_END:-65000}\nSMB_PORT=$((RANDOM % (PORT_RANGE_END - PORT_RANGE_START + 1) + PORT_RANGE_START))\n\n docker rm -f \"$CONTAINER_NAME\" >/dev/null 2>&1 || true\nmkdir -p /opt/amnezia/smb/share\n docker run -d \\\n  --name \"$CONTAINER_NAME\" \\\n  -p \"${SMB_PORT}:445\" \\\n  -v /opt/amnezia/smb/share:/share \\\n  dperson/samba -p -u \"amnezia;amnezia\" -s \"share;/share;yes;no;no;amnezia\"\n echo \"Port: ${SMB_PORT}\"\n echo \"Password: amnezia\"\n',NULL,NULL,'smb://{{server_host}}:{{server_port}}/share\nUsername: amnezia\nPassword: {{password}}',1,1,'2026-10-12 13:06:55','2026-10-12 13:06:55',NULL,'amnezia_compressed',0),(6,'XRay VLESS','xray-vless','XRay VLESS server inside Docker with generated client UUID',NULL,'#!/bin/bash\nset -eu\n\nCONTAINER_NAME=\"${CONTAINER_NAME:-amnezia-xray}\"\nXRAY_PORT=${SERVER_PORT:-443}\n\ndocker pull teddysun/xray >/dev/null 2>&1 || true\n\n# Use existing keys if provided, otherwise generate new ones\nif [ -z \"${PRIVATE_KEY:-}\" ]; then\n  GEN=$(docker run --rm --entrypoint /usr/bin/xray teddysun/xray x25519 2>/dev/null || true)\n  PRIVATE_KEY=$(printf \"%s\\n\" \"$GEN\" | sed -n -E \"s/^[Pp]rivate[Kk]ey:[[:space:]]*(.*)$/\\1/p\" | tr -d \" \\t\\r\\n\")\n  if [ -z \"$PRIVATE_KEY\" ]; then\n    PRIVATE_KEY=$(printf \"%s\\n\" \"$GEN\" | grep -i \"private\" | head -1 | sed \"s/.*:[[:space:]]*//\" | tr -d \" \\t\\r\\n\")\n  fi\nfi\n\n# Derive public key from private key\nPUBLIC_KEY=$(docker run --rm --entrypoint /usr/bin/xray teddysun/xray x25519 -i \"$PRIVATE_KEY\" 2>/dev/null | sed -n -E \"s/^[Pp]ublic[[:space:]]*[Kk]ey:[[:space:]]*(.*)$/\\1/p\" | tr -d \" \\t\\r\\n\" || true)\nif [ -z \"$PUBLIC_KEY\" ]; then\n  PUBLIC_KEY=$(docker run --rm --entrypoint /usr/bin/xray teddysun/xray x25519 -i \"$PRIVATE_KEY\" 2>/dev/null | sed -n -E \"s/^[Pp]assword:[[:space:]]*(.*)$/\\1/p\" | tr -d \" \\t\\r\\n\" || true)\nfi\n\n# Use existing short_id or generate new one\nif [ -z \"${SHORT_ID:-}\" ]; then\n  SHORT_ID=$(od -An -tx1 -N8 /dev/urandom | tr -d \" \\n\")\nfi\n\n# Use existing client_id or generate new one\nif [ -z \"${CLIENT_ID:-}\" ]; then\n  CLIENT_ID=$(cat /proc/sys/kernel/random/uuid)\nfi\n\nSERVER_NAME=\"${SERVER_NAME:-www.googletagmanager.com}\"\nFINGERPRINT=\"${FINGERPRINT:-chrome}\"\nSPIDER_X=\"${SPIDER_X:-/}\"\n\ndocker rm -f \"$CONTAINER_NAME\" >/dev/null 2>&1 || true\nmkdir -p /opt/amnezia/xray\n\ncat > /opt/amnezia/xray/server.json <<EOJSON\n{\n  \"log\": { \"loglevel\": \"warning\" },\n  \"stats\": {},\n  \"api\": {\n    \"tag\": \"api\",\n    \"services\": [ \"StatsService\", \"RoutingService\" ]\n  },\n  \"policy\": {\n    \"levels\": {\n      \"0\": {\n        \"statsUserUplink\": true,\n        \"statsUserDownlink\": true,\n        \"statsUserOnline\": true\n      }\n    },\n    \"system\": {\n      \"statsInboundUplink\": true,\n      \"statsInboundDownlink\": true\n    }\n  },\n  \"inbounds\": [{\n    \"listen\": \"0.0.0.0\",\n    \"port\": ${XRAY_PORT},\n    \"protocol\": \"vless\",\n    \"tag\": \"vless-in\",\n    \"settings\": {\n      \"clients\": [{ \"id\": \"${CLIENT_ID}\", \"flow\": \"xtls-rprx-vision\", \"email\": \"${CLIENT_ID}\", \"level\": 0 }],\n      \"decryption\": \"none\"\n    },\n    \"streamSettings\": {\n      \"network\": \"tcp\",\n      \"security\": \"reality\",\n      \"realitySettings\": {\n        \"show\": false,\n        \"dest\": \"${SERVER_NAME}:443\",\n        \"xver\": 0,\n        \"serverNames\": [\"${SERVER_NAME}\"],\n        \"privateKey\": \"${PRIVATE_KEY}\",\n        \"shortIds\": [\"${SHORT_ID}\"],\n        \"fingerprint\": \"${FINGERPRINT}\",\n        \"spiderX\": \"${SPIDER_X}\"\n      }\n    }\n  },\n  {\n      \"listen\": \"127.0.0.1\",\n      \"port\": 10085,\n      \"protocol\": \"dokodemo-door\",\n      \"tag\": \"api\",\n      \"settings\": {\n        \"address\": \"127.0.0.1\"\n      }\n  }],\n  \"outbounds\": [\n    { \"protocol\": \"freedom\", \"tag\": \"direct\" },\n    { \"protocol\": \"blackhole\", \"tag\": \"blocked\" }\n  ],\n  \"routing\": {\n    \"rules\": [\n      {\n        \"inboundTag\": [ \"api\" ],\n        \"outboundTag\": \"api\",\n        \"type\": \"field\"\n      }\n    ]\n  }\n}\nEOJSON\n\ndocker run -d --name \"$CONTAINER_NAME\" --restart always -p \"${XRAY_PORT}:${XRAY_PORT}\" -v /opt/amnezia/xray:/opt/amnezia/xray teddysun/xray xray run -c /opt/amnezia/xray/server.json\n\nsleep 2\n\necho \"XrayPort: ${XRAY_PORT}\"\necho \"Port: ${XRAY_PORT}\"\necho \"ClientID: ${CLIENT_ID}\"\necho \"PublicKey: ${PUBLIC_KEY}\"\necho \"PrivateKey: ${PRIVATE_KEY}\"\necho \"ShortID: ${SHORT_ID}\"\necho \"ServerName: ${SERVER_NAME}\"\necho \"ContainerName: ${CONTAINER_NAME}\"\n','#!/bin/bash\n\nset -euo pipefail\nset -x\n\nCONTAINER_NAME=\"${SERVER_CONTAINER:-${CONTAINER_NAME:-amnezia-xray}}\"\n\ndocker rm -f \"${CONTAINER_NAME}\" >/dev/null 2>&1 || true\nrm -rf /opt/amnezia/xray || true\n\necho \"Uninstalled: ${CONTAINER_NAME}\"\n',NULL,'vless://{{client_id}}@{{server_host}}:{{server_port}}?encryption=none&flow=xtls-rprx-vision&security=reality&sni={{reality_server_name}}&fp=chrome&pbk={{reality_public_key}}&sid={{reality_short_id}}&type=tcp',1,1,'2026-10-12 13:06:55','2026-10-13 06:32:07','{\n    \"containers\": [\n        {\n            \"container\": \"amnezia-xray\",\n            \"xray\": {\n                \"last_config\": {{last_config_json}},\n                \"port\": \"{{port}}\",\n                \"transport_proto\": \"tcp\"\n            }\n        }\n    ],\n    \"defaultContainer\": \"amnezia-xray\",\n    \"description\": \"{{description}}\",\n    \"dns1\": \"1.1.1.1\",\n    \"dns2\": \"1.0.0.1\",\n    \"hostName\": \"{{hostName}}\"\n}','amnezia_compressed',1),(7,'WireGuard','wireguard','Standard WireGuard','{}',NULL,NULL,NULL,NULL,0,0,'2026-10-12 13:07:09','2026-10-12 13:07:15',NULL,'amnezia_compressed',0),(8,'Cloak','cloak','Cloak obfuscation','{}',NULL,NULL,NULL,NULL,0,0,'2026-10-12 13:07:09','2026-10-12 13:07:15',NULL,'amnezia_compressed',0),(11,'AmneziaWG 2.0','awg2','AmneziaWG 2.0 — userspace Go implementation (amneziawg-go). No kernel module required.','{\"engine\": \"shell\", \"metadata\": {\"config_dir\": \"/opt/amnezia/awg2\", \"port_range\": [30000, 65000], \"vpn_subnet\": \"10.8.1.0/24\", \"container_name\": \"amnezia-awg2\"}}','#!/bin/bash\nset -euo pipefail\n\nCONTAINER_NAME=\"${SERVER_CONTAINER:-amnezia-awg2}\"\nPORT_RANGE_START=${PORT_RANGE_START:-30000}\nPORT_RANGE_END=${PORT_RANGE_END:-65000}\nVPN_PORT=\"${SERVER_PORT:-$((RANDOM % (PORT_RANGE_END - PORT_RANGE_START + 1) + PORT_RANGE_START))}\"\nMTU=${MTU:-1280}\n\nif ! command -v git &> /dev/null; then\n  apt-get update -qq && apt-get install -y -qq git >/dev/null 2>&1\nfi\n\nmkdir -p /opt/amnezia/awg2\n\nif [ ! -d /opt/amnezia/awg2/src ]; then\n  git clone --depth=1 https://github.com/amnezia-vpn/amneziawg-go.git /opt/amnezia/awg2/src\nfi\n\ndocker build --no-cache -t amnezia-awg2 /opt/amnezia/awg2/src\n\nEXISTING=$(docker ps -aq -f \"name=$CONTAINER_NAME\" 2>/dev/null | head -1)\nif [ -z \"$EXISTING\" ]; then\n  docker run -d --name \"$CONTAINER_NAME\" --restart always --cap-add=NET_ADMIN --device /dev/net/tun -p \"${VPN_PORT}:${VPN_PORT}/udp\" -v /opt/amnezia/awg2:/opt/amnezia/awg amnezia-awg2 sh -c \"while [ ! -f /opt/amnezia/awg/awg0.conf ]; do sleep 1; done; WG_QUICK_USERSPACE_IMPLEMENTATION=amneziawg-go awg-quick up /opt/amnezia/awg/awg0.conf && sleep infinity\"\n  sleep 2\nelse\n  STATUS=$(docker inspect --format=\"{{.State.Status}}\" \"$CONTAINER_NAME\" 2>/dev/null || echo \"\")\n  if [ \"$STATUS\" != \"running\" ]; then\n    docker start \"$CONTAINER_NAME\" >/dev/null 2>&1 || true\n  fi\nfi\n# Check for existing config: first on host, then inside container (native Amnezia app installs)\nCONF_FILE=\"/opt/amnezia/awg2/awg0.conf\"\nif [ ! -f \"$CONF_FILE\" ]; then\n  # Try to extract config from inside the container (native Amnezia app stores config without volume mount)\n  CONTAINER_CONF=$(docker exec \"$CONTAINER_NAME\" cat /opt/amnezia/awg/awg0.conf 2>/dev/null || true)\n  if [ -n \"$CONTAINER_CONF\" ] && echo \"$CONTAINER_CONF\" | grep -q \"\\[Interface\\]\"; then\n    mkdir -p /opt/amnezia/awg2\n    echo \"$CONTAINER_CONF\" > /opt/amnezia/awg2/awg0.conf\n    # Also extract keys if available\n    docker exec \"$CONTAINER_NAME\" cat /opt/amnezia/awg/wireguard_server_private_key.key > /opt/amnezia/awg2/wireguard_server_private_key.key 2>/dev/null || true\n    docker exec \"$CONTAINER_NAME\" cat /opt/amnezia/awg/wireguard_server_public_key.key > /opt/amnezia/awg2/wireguard_server_public_key.key 2>/dev/null || true\n    docker exec \"$CONTAINER_NAME\" cat /opt/amnezia/awg/wireguard_psk.key > /opt/amnezia/awg2/wireguard_psk.key 2>/dev/null || true\n    docker exec \"$CONTAINER_NAME\" cat /opt/amnezia/awg/clientsTable > /opt/amnezia/awg2/clientsTable 2>/dev/null || true\n    echo \"Extracted existing config from container\"\n  fi\nfi\n\nif [ -f /opt/amnezia/awg2/awg0.conf ]; then\n  PORT=$(grep -E \"^ListenPort\" /opt/amnezia/awg2/awg0.conf | cut -d= -f2 | tr -d \"[:space:]\")\n  PSK=$(cat /opt/amnezia/awg2/wireguard_psk.key 2>/dev/null || true)\n  if [ -z \"$PSK\" ]; then\n    PSK=$(grep -E \"^PresharedKey\" /opt/amnezia/awg2/awg0.conf | head -1 | cut -d= -f2 | tr -d \"[:space:]\")\n  fi\n  PUBKEY=$(cat /opt/amnezia/awg2/wireguard_server_public_key.key 2>/dev/null || true)\n  if [ -z \"$PUBKEY\" ]; then\n    PRIVKEY=$(cat /opt/amnezia/awg2/wireguard_server_private_key.key 2>/dev/null || true)\n    if [ -n \"$PRIVKEY\" ]; then\n      PUBKEY=$(echo \"$PRIVKEY\" | docker exec -i \"$CONTAINER_NAME\" wg pubkey)\n    fi\n  fi\n\n  echo \"Using existing AmneziaWG 2.0 configuration\"\n  echo \"Port: ${PORT:-$VPN_PORT}\"\n  if [ -n \"${PUBKEY:-}\" ]; then echo \"Server Public Key: $PUBKEY\"; fi\n  if [ -n \"${PSK:-}\" ]; then echo \"PresharedKey = $PSK\"; fi\n\n  EXTERNAL_IP=$(curl -s -4 ifconfig.me 2>/dev/null || curl -s -4 icanhazip.com 2>/dev/null || echo \"YOUR_SERVER_IP\")\n  echo \"Server Host: $EXTERNAL_IP\"\n\n  for P in Jc Jmin Jmax S1 S2 S3 S4 H1 H2 H3 H4 I1 I2 I3 I4 I5; do\n    VAL=$(sed -n -E \"s/^[[:space:]]*$P[[:space:]]*=[[:space:]]*//p\" /opt/amnezia/awg2/awg0.conf | head -1 | tr -d \"\\r\")\n    if [ -n \"$VAL\" ] || [[ \"$P\" =~ ^I[2-5]$ ]]; then echo \"Variable: $P=$VAL\"; fi\n  done\n  echo \"Variable: dns_servers=1.1.1.1, 1.0.0.1\"\n  exit 0\nfi\n\nPRIVATE_KEY=$(docker exec \"$CONTAINER_NAME\" wg genkey)\nPUBLIC_KEY=$(echo \"$PRIVATE_KEY\" | docker exec -i \"$CONTAINER_NAME\" wg pubkey)\nPRESHARED_KEY=$(docker exec \"$CONTAINER_NAME\" wg genpsk)\n\nJC=5\nJMIN=10\nJMAX=50\nS1_VAL=51\nS2_VAL=125\nS3_VAL=13\nS4_VAL=9\nH1_VAL=\"1443912531-1981073285\"\nH2_VAL=\"1984025557-2135018048\"\nH3_VAL=\"2145217268-2146643749\"\nH4_VAL=\"2146790761-2146860793\"\nI1_VAL=\"<r 2><b 0x858000010001000000000669636c6f756403636f6d0000010001c00c000100010000105a00044d583737>\"\nI2_VAL=\"\"\nI3_VAL=\"\"\nI4_VAL=\"\"\nI5_VAL=\"\"\n\n{\necho \"[Interface]\"\necho \"PrivateKey = $PRIVATE_KEY\"\necho \"Address = 10.8.1.1/24\"\necho \"ListenPort = $VPN_PORT\"\necho \"Jc = $JC\"\necho \"Jmin = $JMIN\"\necho \"Jmax = $JMAX\"\necho \"S1 = $S1_VAL\"\necho \"S2 = $S2_VAL\"\necho \"S3 = $S3_VAL\"\necho \"S4 = $S4_VAL\"\necho \"H1 = $H1_VAL\"\necho \"H2 = $H2_VAL\"\necho \"H3 = $H3_VAL\"\necho \"H4 = $H4_VAL\"\necho \"I1 = $I1_VAL\"\necho \"PostUp = iptables -A FORWARD -i %i -j ACCEPT; iptables -A FORWARD -o %i -j ACCEPT; iptables -t nat -A POSTROUTING -o eth0 -j MASQUERADE\"\necho \"PostDown = iptables -D FORWARD -i %i -j ACCEPT; iptables -D FORWARD -o %i -j ACCEPT; iptables -t nat -D POSTROUTING -o eth0 -j MASQUERADE\"\n} > /opt/amnezia/awg2/awg0.conf\n\necho \"$PRIVATE_KEY\" > /opt/amnezia/awg2/wireguard_server_private_key.key\necho \"$PUBLIC_KEY\" > /opt/amnezia/awg2/wireguard_server_public_key.key\necho \"$PRESHARED_KEY\" > /opt/amnezia/awg2/wireguard_psk.key\necho \"[]\" > /opt/amnezia/awg2/clientsTable\n\nEXTERNAL_IP=$(curl -s -4 ifconfig.me 2>/dev/null || curl -s -4 icanhazip.com 2>/dev/null || echo \"YOUR_SERVER_IP\")\n\necho \"AmneziaWG 2.0 installed successfully\"\necho \"Port: $VPN_PORT\"\necho \"Server Public Key: $PUBLIC_KEY\"\necho \"PresharedKey = $PRESHARED_KEY\"\necho \"Server Host: $EXTERNAL_IP\"\necho \"Variable: Jc=$JC\"\necho \"Variable: Jmin=$JMIN\"\necho \"Variable: Jmax=$JMAX\"\necho \"Variable: S1=$S1_VAL\"\necho \"Variable: S2=$S2_VAL\"\necho \"Variable: S3=$S3_VAL\"\necho \"Variable: S4=$S4_VAL\"\necho \"Variable: H1=$H1_VAL\"\necho \"Variable: H2=$H2_VAL\"\necho \"Variable: H3=$H3_VAL\"\necho \"Variable: H4=$H4_VAL\"\necho \"Variable: I1=$I1_VAL\"\necho \"Variable: dns_servers=1.1.1.1, 1.0.0.1\"','#!/bin/bash\nset -euo pipefail\n\nCONTAINER_NAME=\"${CONTAINER_NAME:-amnezia-awg2}\"\n\ndocker stop \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker rm -fv \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker image rm amnezia-awg2 2>/dev/null || true\nrm -rf /opt/amnezia/awg2 2>/dev/null || true\n\necho \"{\"success\":true,\"message\":\"AmneziaWG 2.0 uninstalled\"}\"',NULL,'[Interface]\nAddress = {{client_ip}}/32\nDNS = {{dns_servers}}\nPrivateKey = {{private_key}}\nJc = {{Jc}}\nJmin = {{Jmin}}\nJmax = {{Jmax}}\nS1 = {{S1}}\nS2 = {{S2}}\nS3 = {{S3}}\nS4 = {{S4}}\nH1 = {{H1}}\nH2 = {{H2}}\nH3 = {{H3}}\nH4 = {{H4}}\nI1 = {{I1}}\nI2 = {{I2}}\nI3 = {{I3}}\nI4 = {{I4}}\nI5 = {{I5}}\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nAllowedIPs = 0.0.0.0/0, ::/0\nEndpoint = {{server_host}}:{{server_port}}\nPersistentKeepalive = 25',1,1,'2026-10-12 13:07:15','2026-10-13 06:32:08',NULL,'amnezia_compressed',0),(12,'MTProxy (Telegram)','mtproxy','Telegram MTProto proxy — zero-configuration proxy server for Telegram messenger.','{\"engine\": \"shell\", \"metadata\": {\"config_dir\": \"/opt/amnezia/mtproxy\", \"port_range\": [30000, 65000], \"container_name\": \"amnezia-mtproxy\"}}','#!/bin/bash\nset -euo pipefail\n\n# Use exported variables from panel (SERVER_PORT, SERVER_CONTAINER) or defaults\nCONTAINER_NAME=\"${SERVER_CONTAINER:-amnezia-mtproxy}\"\nPORT_RANGE_START=${PORT_RANGE_START:-30000}\nPORT_RANGE_END=${PORT_RANGE_END:-65000}\nMTPROXY_PORT=\"${SERVER_PORT:-$((RANDOM % (PORT_RANGE_END - PORT_RANGE_START + 1) + PORT_RANGE_START))}\"\n\nmkdir -p /opt/amnezia/mtproxy\n\n# Generate secret if not exists\nif [ -f /opt/amnezia/mtproxy/secret ]; then\n  SECRET=$(cat /opt/amnezia/mtproxy/secret)\n  echo \"Using existing MTProxy secret\"\nelse\n  SECRET=$(cat /dev/urandom | tr -dc a-f0-9 | head -c 32 || true)\n  echo \"$SECRET\" > /opt/amnezia/mtproxy/secret\nfi\n\n# Store port\necho \"$MTPROXY_PORT\" > /opt/amnezia/mtproxy/port\n\n# Remove existing container\ndocker rm -f \"$CONTAINER_NAME\" >/dev/null 2>&1 || true\n\n# Run MTProxy container (single line for heredoc compatibility)\ndocker run -d --name \"$CONTAINER_NAME\" --restart always -p \"${MTPROXY_PORT}:443\" -v /opt/amnezia/mtproxy:/data -e SECRET=\"$SECRET\" telegrammessenger/proxy:latest\n\nsleep 3\n\n# Get external IP\nEXTERNAL_IP=$(curl -s -4 ifconfig.me 2>/dev/null || curl -s -4 icanhazip.com 2>/dev/null || echo \"YOUR_SERVER_IP\")\n\necho \"MTProxy installed successfully\"\necho \"Port: $MTPROXY_PORT\"\necho \"Secret: $SECRET\"\necho \"Server Host: $EXTERNAL_IP\"','#!/bin/bash\nset -euo pipefail\n\nCONTAINER_NAME=\"${CONTAINER_NAME:-amnezia-mtproxy}\"\n\ndocker stop \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker rm -fv \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker image rm telegrammessenger/proxy:latest 2>/dev/null || true\nrm -rf /opt/amnezia/mtproxy 2>/dev/null || true\n\necho \"{\"success\":true,\"message\":\"MTProxy uninstalled\"}\"',NULL,'tg://proxy?server={{server_host}}&port={{server_port}}&secret={{secret}}',1,1,'2026-10-12 13:07:16','2026-10-12 13:07:17','tg://proxy?server={{server_host}}&port={{server_port}}&secret={{secret}}','raw',1),(13,'AIVPN','aivpn','AIVPN — AI-powered VPN с маскировкой трафика под реальные приложения (Zoom, TikTok, DNS). Neural Resonance для обхода DPI.','{\"engine\": \"shell\", \"metadata\": {\"version\": \"v0.9.1\", \"git_repo\": \"https://github.com/infosave2007/aivpn.git\", \"config_dir\": \"/etc/aivpn\", \"port_range\": [443, 443], \"vpn_subnet\": \"10.0.0.0/24\", \"build_method\": \"dockerfile_prebuilt\", \"container_name\": \"aivpn-server\", \"requires_docker_build\": true}}','#!/bin/bash\nset -eo pipefail\n\n# Use exported variables from panel (SERVER_PORT, SERVER_CONTAINER) or defaults\nCONTAINER_NAME=\"${SERVER_CONTAINER:-aivpn-server}\"\nVPN_PORT=\"${SERVER_PORT:-443}\"\nCONFIG_DIR=\"/etc/aivpn\"\nAIVPN_VERSION=\"v0.9.1\"\n\n# Install Docker if not available\nif ! command -v docker &> /dev/null; then\n  apt-get update -qq\n  apt-get install -y -qq apt-transport-https ca-certificates curl gnupg lsb-release >/dev/null 2>&1\n  curl -fsSL https://download.docker.com/linux/ubuntu/gpg | gpg --dearmor -o /usr/share/keyrings/docker-archive-keyring.gpg\n  echo \"deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/docker-archive-keyring.gpg] https://download.docker.com/linux/ubuntu $(lsb_release -cs) stable\" > /etc/apt/sources.list.d/docker.list\n  apt-get update -qq && apt-get install -y -qq docker-ce docker-ce-cli containerd.io >/dev/null 2>&1\nfi\n\n# Install git, iptables, curl if not available\nif ! command -v git &> /dev/null || ! command -v iptables &> /dev/null || ! command -v curl &> /dev/null; then\n  apt-get update -qq\n  if ! command -v git &> /dev/null; then\n    apt-get install -y -qq git >/dev/null 2>&1\n  fi\n  if ! command -v iptables &> /dev/null; then\n    apt-get install -y -qq iptables >/dev/null 2>&1\n  fi\n  if ! command -v curl &> /dev/null; then\n    apt-get install -y -qq curl >/dev/null 2>&1\n  fi\nfi\n\nmkdir -p \"$CONFIG_DIR\"\n\n# Enable IP forwarding\nsysctl -w net.ipv4.ip_forward=1 2>/dev/null || true\n\n# Generate server key if not exists\nif [ ! -f \"$CONFIG_DIR/server.key\" ]; then\n  openssl rand 32 > \"$CONFIG_DIR/server.key\"\n  chmod 600 \"$CONFIG_DIR/server.key\"\n  echo \"Generated new AIVPN server key\"\nelse\n  echo \"Using existing AIVPN server key\"\nfi\n\n# Setup NAT - find default interface\nDEFAULT_IFACE=\"\"\nif command -v ip >/dev/null 2>&1; then\n  DEFAULT_IFACE=$(ip route show default 2>/dev/null | grep default | head -1 | tr -s \" \" | cut -d\" \" -f5)\nelif command -v route >/dev/null 2>&1; then\n  DEFAULT_IFACE=$(route -n 2>/dev/null | grep \"^0.0.0.0\" | head -1 | tr -s \" \" | cut -d\" \" -f8)\nelif [ -d /sys/class/net ]; then\n  # Fallback: try common interface names\n  for iface in eth0 ens3 enp0s3 wlan0; do\n    if [ -d \"/sys/class/net/$iface\" ]; then\n      DEFAULT_IFACE=$iface\n      break\n    fi\n  done\nfi\n\nif [ -n \"$DEFAULT_IFACE\" ]; then\n  iptables -t nat -C POSTROUTING -s 10.0.0.0/24 -o \"$DEFAULT_IFACE\" -j MASQUERADE 2>/dev/null || \n    iptables -t nat -A POSTROUTING -s 10.0.0.0/24 -o \"$DEFAULT_IFACE\" -j MASQUERADE\nelse\n  echo \"WARNING: Could not determine default network interface, skipping NAT setup\"\nfi\n\n# Allow forwarding for the VPN subnet. On Docker hosts the FORWARD policy is DROP,\n# and the AIVPN TUN interface is not covered by Docker\'s own FORWARD rules, so without\n# these explicit ACCEPT rules client traffic is forwarded out (MASQUERADE) but the\n# return path is dropped (clients connect/handshake but get no traffic — bytes_out=0).\niptables -C FORWARD -s 10.0.0.0/24 -j ACCEPT 2>/dev/null || iptables -I FORWARD 1 -s 10.0.0.0/24 -j ACCEPT\niptables -C FORWARD -d 10.0.0.0/24 -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT 2>/dev/null || iptables -I FORWARD 1 -d 10.0.0.0/24 -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT\n\n# Get external IP\nEXTERNAL_IP=$(curl -s -4 ifconfig.me 2>/dev/null || curl -s -4 icanhazip.com 2>/dev/null || echo \"YOUR_SERVER_IP\")\n\n# Clone AIVPN repository at the target release tag (mask-assets must match the binary)\nAIVPN_DIR=\"/opt/amnezia/aivpn\"\nif [ ! -d \"$AIVPN_DIR/.git\" ]; then\n  echo \"Cloning AIVPN repository at $AIVPN_VERSION...\"\n  rm -rf \"$AIVPN_DIR\"\n  git clone --depth=1 --branch \"$AIVPN_VERSION\" https://github.com/infosave2007/aivpn.git \"$AIVPN_DIR\"\nelse\n  echo \"Updating AIVPN repository to $AIVPN_VERSION...\"\n  git -C \"$AIVPN_DIR\" fetch --depth=1 origin \"tag\" \"$AIVPN_VERSION\"\n  git -C \"$AIVPN_DIR\" checkout -f \"$AIVPN_VERSION\"\nfi\n\ncd \"$AIVPN_DIR\"\n\n# Download prebuilt binary directly from repository\necho \"Downloading prebuilt AIVPN server binary...\"\nDOWNLOAD_URL=\"https://github.com/infosave2007/aivpn/releases/download/${AIVPN_VERSION}/aivpn-server-linux-x86_64\"\n\nif [ -z \"$DOWNLOAD_URL\" ]; then\n  echo \"ERROR: Could not find download URL for aivpn-server-linux-x86_64\"\n  exit 1\nfi\n\necho \"Downloading from: $DOWNLOAD_URL\"\ncurl -L -o aivpn-server-linux-x86_64 \"$DOWNLOAD_URL\"\n\nif [ ! -f \"./aivpn-server-linux-x86_64\" ]; then\n  echo \"ERROR: Binary download failed\"\n  exit 1\nfi\n\nchmod +x ./aivpn-server-linux-x86_64\necho \"Binary downloaded successfully: $(ls -lh aivpn-server-linux-x86_64)\"\n\n# Check /dev/net/tun exists\nif [ ! -c /dev/net/tun ]; then\n  echo \"Creating /dev/net/tun...\"\n  mkdir -p /dev/net\n  mknod /dev/net/tun c 10 200\n  chmod 666 /dev/net/tun\nfi\n\n# Remove existing container\ndocker rm -f \"$CONTAINER_NAME\" >/dev/null 2>&1 || true\n\n# Go back to AIVPN root directory\ncd /opt/amnezia/aivpn\n\n# Create docker-entrypoint.sh as a separate file (to avoid Docker build variable expansion issues)\ncat > docker-entrypoint.sh << \'ENTRYPOINT_EOF\'\n#!/bin/sh\nset -eu\n\nmkdir -p /etc/aivpn /var/lib/aivpn/masks\n\n# Seed preset masks on first run\nPRESET_DIR=\"/usr/share/aivpn/preset-masks\"\nif [ -d \"$PRESET_DIR\" ]; then\n    for f in \"$PRESET_DIR\"/*.json; do\n        [ -f \"$f\" ] || continue\n        base=\"$(basename \"$f\")\"\n        if [ ! -f \"/var/lib/aivpn/masks/$base\" ]; then\n            cp \"$f\" \"/var/lib/aivpn/masks/$base\"\n        fi\n    done\nfi\n\nexec /usr/local/bin/aivpn-server \"$@\"\nENTRYPOINT_EOF\nchmod +x docker-entrypoint.sh\n\n# Always create/update Dockerfile.prebuilt\ncat > Dockerfile.prebuilt << \'DOCKERFILE\'\nFROM ubuntu:24.04\n\n# Install runtime dependencies (single line to avoid backslash issues)\nRUN apt-get update && apt-get install -y ca-certificates iptables iproute2 netcat-openbsd python3 bc libstdc++6 && rm -rf /var/lib/apt/lists/*\n\nWORKDIR /app\n\n# Copy prebuilt Linux server binary from releases/\nCOPY aivpn-server-linux-x86_64 /usr/local/bin/aivpn-server\nRUN chmod +x /usr/local/bin/aivpn-server\n\n# Create config directory, masks directory, and TUN device node (single line to avoid backslash issues)\nRUN mkdir -p /etc/aivpn /var/lib/aivpn/masks /var/lib/aivpn/bootstrap /usr/share/aivpn/preset-masks /dev/net && mknod /dev/net/tun c 10 200 2>/dev/null || true && chmod 666 /dev/net/tun\n\n# Copy mask assets to preset directory (v0.9.1 moved them under aivpn-common/)\nCOPY aivpn-common/mask-assets/*.json /usr/share/aivpn/preset-masks/\n\n# Copy prebuilt entrypoint script\nCOPY docker-entrypoint.sh /usr/local/bin/docker-entrypoint.sh\nRUN chmod +x /usr/local/bin/docker-entrypoint.sh\n\nENTRYPOINT [\"/usr/local/bin/docker-entrypoint.sh\"]\nCMD [\"--listen\", \"0.0.0.0:443\", \"--key-file\", \"/etc/aivpn/server.key\", \"--clients-db\", \"/etc/aivpn/clients.json\"]\nDOCKERFILE\n\n# Build Docker image using Dockerfile.prebuilt\necho \"Building AIVPN Docker image from prebuilt binary...\"\ndocker build -t aivpn-server:local -f Dockerfile.prebuilt .\n\n# Run AIVPN container\necho \"Running AIVPN container...\"\nRUN_OUTPUT=$(docker run -d --name \"$CONTAINER_NAME\" --restart always --cap-add=NET_ADMIN --device /dev/net/tun --network host -v \"$CONFIG_DIR:/etc/aivpn\" -v /var/lib/aivpn/masks:/var/lib/aivpn/masks aivpn-server:local --listen \"0.0.0.0:${VPN_PORT}\" --key-file /etc/aivpn/server.key --clients-db /etc/aivpn/clients.json 2>&1)\nRUN_EXIT=$?\necho \"docker run exit code: $RUN_EXIT\"\necho \"docker run output: $RUN_OUTPUT\"\n\nsleep 3\n\n# Check container exists\necho \"Checking container...\"\nCONTAINER_EXISTS=$(docker ps -a --filter \"name=$CONTAINER_NAME\" --format {{.Names}} 2>/dev/null)\necho \"Container exists: $CONTAINER_EXISTS\"\n\nif [ -z \"$CONTAINER_EXISTS\" ]; then\n  echo \"ERROR: Container was not created\"\n  exit 1\nfi\n\n# Check container status\nSTATUS=$(docker inspect --format={{.State.Status}} \"$CONTAINER_NAME\" 2>/dev/null || echo \"\")\nif [ -z \"$STATUS\" ]; then\n  STATUS=\"unknown\"\nfi\necho \"Container status: $STATUS\"\n\nif [ \"$STATUS\" != \"running\" ]; then\n  echo \"ERROR: AIVPN container is not running (status: $STATUS)\"\n  echo \"=== Container logs ===\"\n  docker logs \"$CONTAINER_NAME\" 2>&1 || echo \"No logs available\"\n  echo \"=== Container inspect ===\"\n  docker inspect \"$CONTAINER_NAME\" 2>&1 || echo \"Container not found\"\n  exit 1\nfi\n\necho \"AIVPN installed successfully\"\n# Output variables for the web panel parser\nKEY_B64=$(base64 -w 0 \"$CONFIG_DIR/server.key\" 2>/dev/null || base64 \"$CONFIG_DIR/server.key\")\necho \"Variable: connection_key=$KEY_B64\"\necho \"Variable: server_host=$EXTERNAL_IP\"\necho \"Variable: server_port=$VPN_PORT\"\necho \"Variable: config_dir=$CONFIG_DIR\"','#!/bin/bash\nset -euo pipefail\n\nCONTAINER_NAME=\"${CONTAINER_NAME:-aivpn-server}\"\n\ndocker stop \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker rm -fv \"$CONTAINER_NAME\" 2>/dev/null || true\ndocker image rm aivpn-server 2>/dev/null || true\nrm -rf /opt/amnezia/aivpn 2>/dev/null || true\n\n# Remove NAT rules\niptables -t nat -D POSTROUTING -s 10.0.0.0/24 -o eth0 -j MASQUERADE 2>/dev/null || true\n\necho \"{\"success\":true,\"message\":\"AIVPN uninstalled\"}\"',NULL,'aivpn://{{connection_key}}',1,1,'2026-10-12 13:07:17','2026-10-13 06:32:10',NULL,'amnezia_compressed',1),(14,'Cloudflare WARP Proxy','cf-warp','Cloudflare WARP — прокси-слой для обхода DPI/цензуры. Устанавливает WARP на сервер в режиме SOCKS5 прокси (127.0.0.1:40000). Трафик идёт по цепочке: VPN-клиент → AmneziaWG → WARP → Cloudflare → Интернет. Скрывает конечные домены от провайдера VPS.','{\"engine\": \"shell\", \"metadata\": {\"config_dir\": \"/var/lib/cloudflare-warp\", \"port_range\": [40000, 40000], \"proxy_port\": 40000, \"container_name\": \"\", \"is_proxy_layer\": true, \"proxy_protocol\": \"socks5\"}}','#!/bin/bash\n\n# ======================================================================\n# Cloudflare WARP Proxy Installer v4 (AWG + AIVPN + X-Ray)\n# Installs WARP + redsocks, auto-routes ALL VPN client traffic through CF\n# ======================================================================\n\nWARP_PROXY_PORT=\"${WARP_PROXY_PORT:-40000}\"\nWARP_MODE=\"${WARP_MODE:-proxy}\"\nREDSOCKS_PORT=\"${REDSOCKS_PORT:-12345}\"\n\nexport DEBIAN_FRONTEND=noninteractive\n\necho \"=== Installing Cloudflare WARP v4 ===\"\n\n# Detect OS\nif [ -f /etc/os-release ]; then\n  . /etc/os-release\n  OS_ID=\"$ID\"\n  OS_VERSION=\"$VERSION_ID\"\nelse\n  OS_ID=\"unknown\"\n  OS_VERSION=\"0\"\nfi\necho \"OS: $OS_ID $OS_VERSION\"\n\nARCH=$(uname -m)\nif [ \"$ARCH\" != \"x86_64\" ] && [ \"$ARCH\" != \"aarch64\" ]; then\n  echo \"FAIL: WARP supports only x86_64 and aarch64, got: $ARCH\"\n  exit 1\nfi\n\nTOTAL_RAM_MB=$(free -m 2>/dev/null | awk \"/^Mem:/{print $2}\" || echo \"0\")\nif [ \"$TOTAL_RAM_MB\" -gt 0 ] && [ \"$TOTAL_RAM_MB\" -lt 512 ]; then\n  echo \"NOTE: Low RAM ${TOTAL_RAM_MB}MB. WARP needs ~100MB.\"\nfi\n\napt-get update -qq\napt-get install -y -qq curl gnupg lsb-release >/dev/null 2>&1\n\ncurl -fsSL https://pkg.cloudflareclient.com/pubkey.gpg | gpg --yes --dearmor -o /usr/share/keyrings/cloudflare-warp-archive-keyring.gpg\n\nREPO_CODENAME=\"\"\ncase \"$OS_ID\" in\n  ubuntu)\n    case \"$OS_VERSION\" in\n      24.04) REPO_CODENAME=\"noble\" ;;\n      22.04) REPO_CODENAME=\"jammy\" ;;\n      20.04) REPO_CODENAME=\"focal\" ;;\n      *)     REPO_CODENAME=\"jammy\" ;;\n    esac\n    ;;\n  debian)\n    case \"$OS_VERSION\" in\n      12*) REPO_CODENAME=\"bookworm\" ;;\n      11*) REPO_CODENAME=\"bullseye\" ;;\n      *)   REPO_CODENAME=\"bookworm\" ;;\n    esac\n    ;;\n  *)\n    REPO_CODENAME=\"jammy\"\n    ;;\nesac\n\necho \"deb [signed-by=/usr/share/keyrings/cloudflare-warp-archive-keyring.gpg] https://pkg.cloudflareclient.com/ $REPO_CODENAME main\" > /etc/apt/sources.list.d/cloudflare-client.list\n\napt-get update -qq\napt-get install -y -qq cloudflare-warp >/dev/null 2>&1\necho \"WARP package installed\"\n\nWARP_STATUS=$(warp-cli --accept-tos status 2>/dev/null || echo \"unregistered\")\nif echo \"$WARP_STATUS\" | grep -qiE \"Registration Missing|unregistered\"; then\n  warp-cli --accept-tos registration new\n  echo \"WARP registered\"\nelse\n  echo \"WARP already registered\"\nfi\n\nwarp-cli --accept-tos mode proxy\nwarp-cli --accept-tos proxy port \"$WARP_PROXY_PORT\"\nwarp-cli --accept-tos connect\necho \"WARP connecting...\"\n\nfor i in $(seq 1 15); do\n  CONN_STATUS=$(warp-cli --accept-tos status 2>/dev/null || echo \"\")\n  if echo \"$CONN_STATUS\" | grep -qi \"Connected\"; then\n    echo \"WARP connected\"\n    break\n  fi\n  sleep 2\ndone\n\nsleep 2\nLISTENING=\"\"\nif command -v ss >/dev/null 2>&1; then\n  LISTENING=$(ss -tlnp 2>/dev/null | grep \":${WARP_PROXY_PORT}\" || true)\nfi\nif [ -n \"$LISTENING\" ]; then\n  echo \"WARP SOCKS5 proxy on 127.0.0.1:${WARP_PROXY_PORT} OK\"\nelse\n  echo \"NOTE: Proxy port ${WARP_PROXY_PORT} not yet listening\"\nfi\n\nPROXY_TEST=$(curl -x socks5h://127.0.0.1:${WARP_PROXY_PORT} -s -o /dev/null -w \"%{http_code}\" --max-time 10 https://cloudflare.com/cdn-cgi/trace 2>/dev/null || echo \"000\")\nif [ \"$PROXY_TEST\" = \"200\" ]; then\n  echo \"WARP proxy test OK\"\nfi\n\nWARP_IP=$(curl -x socks5h://127.0.0.1:${WARP_PROXY_PORT} -s --max-time 10 https://cloudflare.com/cdn-cgi/trace 2>/dev/null | grep \"ip=\" | cut -d= -f2 || echo \"unknown\")\nWARP_ACCOUNT=$(warp-cli --accept-tos registration show 2>/dev/null | grep -i \"Account ID\" | awk \"{print $NF}\" || echo \"unknown\")\n\nsystemctl enable warp-svc 2>/dev/null || true\n\n# ── AUTO-ROUTING: redsocks + iptables ──\necho \"=== Setting up redsocks auto-routing ===\"\n\napt-get install -y -qq redsocks >/dev/null 2>&1 || true\n\nREDSOCKS_BIN=$(command -v redsocks 2>/dev/null || echo \"\")\nif [ -z \"$REDSOCKS_BIN\" ]; then\n  if [ -f /usr/sbin/redsocks ]; then\n    REDSOCKS_BIN=\"/usr/sbin/redsocks\"\n  fi\nfi\n\nif [ -n \"$REDSOCKS_BIN\" ]; then\n  echo \"redsocks binary: $REDSOCKS_BIN\"\n\n  mkdir -p /etc/redsocks\n  printf \"base {\\n  log_debug = off;\\n  log_info = on;\\n  log = \\\"syslog:daemon\\\";\\n  daemon = on;\\n  redirector = iptables;\\n}\\nredsocks {\\n  local_ip = 0.0.0.0;\\n  local_port = %s;\\n  ip = 127.0.0.1;\\n  port = %s;\\n  type = socks5;\\n}\\n\" \"$REDSOCKS_PORT\" \"$WARP_PROXY_PORT\" > /etc/redsocks/redsocks.conf\n  echo \"redsocks config created\"\n\n  printf \"[Unit]\\nDescription=Redsocks WARP transparent proxy\\nAfter=network.target warp-svc.service\\nWants=warp-svc.service\\n\\n[Service]\\nType=forking\\nExecStart=%s -c /etc/redsocks/redsocks.conf\\nRestart=on-failure\\nRestartSec=5\\n\\n[Install]\\nWantedBy=multi-user.target\\n\" \"$REDSOCKS_BIN\" > /etc/systemd/system/redsocks-warp.service\n  echo \"systemd service created\"\n\n  systemctl stop redsocks 2>/dev/null || true\n  systemctl stop redsocks-warp 2>/dev/null || true\n  killall redsocks 2>/dev/null || true\n  systemctl daemon-reload\n  systemctl enable redsocks-warp 2>/dev/null || true\n  systemctl start redsocks-warp 2>/dev/null || true\n  echo \"redsocks-warp started\"\n\n  ROUTED_SUBNETS=\"\"\n  CONTAINER_IPS=\"\"\n\n  # 1. Detect AWG container IPs (containers MASQUERADE VPN traffic,\n  #    so on the host we see src=container_IP, not VPN subnet)\n  for container in $(docker ps --format \"{{`{{.Names}}`}}\" 2>/dev/null | grep -iE \"amnezia-awg|awg\" || true); do\n    CIP=$(docker inspect -f \"{{`{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}`}}\" \"$container\" 2>/dev/null || true)\n    if [ -n \"$CIP\" ]; then\n      CONTAINER_IPS=\"$CONTAINER_IPS $CIP\"\n      echo \"AWG container $container IP: $CIP\"\n    fi\n  done\n\n  # 2. Detect host-level VPN subnets (aivpn0, wg0, etc.)\n  for iface in aivpn0 wg0 wg1; do\n    ADDR=$(ip -4 addr show \"$iface\" 2>/dev/null | grep -oP \"inet \\K[0-9./]+\" | head -1 || true)\n    if [ -n \"$ADDR\" ]; then\n      NET=$(echo \"$ADDR\" | sed -E \"s/([0-9]+\\.[0-9]+\\.[0-9]+)\\.[0-9]+(.*)/\\1.0\\2/\")\n      if ! echo \"$ROUTED_SUBNETS\" | grep -q \"$NET\"; then\n        ROUTED_SUBNETS=\"$ROUTED_SUBNETS $NET\"\n        echo \"VPN subnet from $iface: $NET\"\n      fi\n    fi\n  done\n\n  # 3. Fallback if nothing detected\n  if [ -z \"$ROUTED_SUBNETS\" ] && [ -z \"$CONTAINER_IPS\" ]; then\n    ROUTED_SUBNETS=\"10.8.1.0/24 10.0.0.0/24\"\n    echo \"Default subnets: 10.8.1.0/24 10.0.0.0/24\"\n  fi\n\n  # Enable route_localnet so DNAT to 127.0.0.1 works for Docker traffic\n  sysctl -w net.ipv4.conf.docker0.route_localnet=1 2>/dev/null || true\n  sysctl -w net.ipv4.conf.all.route_localnet=1 2>/dev/null || true\n  grep -q route_localnet /etc/sysctl.d/99-warp.conf 2>/dev/null || {\n    mkdir -p /etc/sysctl.d\n    echo \"net.ipv4.conf.docker0.route_localnet=1\" >> /etc/sysctl.d/99-warp.conf\n    echo \"net.ipv4.conf.all.route_localnet=1\" >> /etc/sysctl.d/99-warp.conf\n  }\n\n  iptables -t nat -N REDSOCKS_WARP 2>/dev/null || iptables -t nat -F REDSOCKS_WARP\n  iptables -t nat -A REDSOCKS_WARP -d 0.0.0.0/8 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -d 10.0.0.0/8 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -d 100.64.0.0/10 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -d 127.0.0.0/8 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -d 169.254.0.0/16 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -d 172.16.0.0/12 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -d 192.168.0.0/16 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -d 224.0.0.0/4 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -d 240.0.0.0/4 -j RETURN 2>/dev/null || true\n  iptables -t nat -A REDSOCKS_WARP -p tcp -j REDIRECT --to-ports ${REDSOCKS_PORT} 2>/dev/null || true\n\n  # Add rules for host-level VPN subnets\n  for SUBNET in $ROUTED_SUBNETS; do\n    iptables -t nat -D PREROUTING -s \"$SUBNET\" -p tcp -j REDSOCKS_WARP 2>/dev/null || true\n    iptables -t nat -A PREROUTING -s \"$SUBNET\" -p tcp -j REDSOCKS_WARP 2>/dev/null || true\n    echo \"Routing subnet $SUBNET through WARP\"\n  done\n\n  # Add rules for AWG container IPs (traffic exits container MASQUERADEd)\n  for CIP in $CONTAINER_IPS; do\n    iptables -t nat -D PREROUTING -s \"$CIP\" -p tcp -j REDSOCKS_WARP 2>/dev/null || true\n    iptables -t nat -A PREROUTING -s \"$CIP\" -p tcp -j REDSOCKS_WARP 2>/dev/null || true\n    echo \"Routing container $CIP through WARP\"\n  done\n\n  mkdir -p /var/lib/cloudflare-warp\n  echo \"$ROUTED_SUBNETS $CONTAINER_IPS\" > /var/lib/cloudflare-warp/routed_subnets\n  echo \"Auto-routing active\"\nelse\n  echo \"NOTE: redsocks not available, auto-routing skipped\"\n  echo \"Manual proxy: socks5h://127.0.0.1:${WARP_PROXY_PORT}\"\nfi\n\nEXTERNAL_IP=$(curl -s -4 ifconfig.me 2>/dev/null || curl -s -4 icanhazip.com 2>/dev/null || echo \"YOUR_SERVER_IP\")\n\necho \"\"\necho \"=== Cloudflare WARP Installed ===\"\necho \"Variable: warp_proxy_port=$WARP_PROXY_PORT\"\necho \"Variable: warp_mode=$WARP_MODE\"\necho \"Variable: warp_ip=$WARP_IP\"\necho \"Variable: warp_account=$WARP_ACCOUNT\"\necho \"Variable: server_host=$EXTERNAL_IP\"\necho \"Variable: proxy_address=127.0.0.1:${WARP_PROXY_PORT}\"\necho \"Variable: redsocks_port=$REDSOCKS_PORT\"\necho \"Variable: routed_subnets=$ROUTED_SUBNETS\"','#!/bin/bash\n\necho \"=== Uninstalling Cloudflare WARP ===\"\n\nROUTED_SUBNETS=\"\"\nif [ -f /var/lib/cloudflare-warp/routed_subnets ]; then\n  ROUTED_SUBNETS=$(cat /var/lib/cloudflare-warp/routed_subnets)\nfi\nif [ -z \"$ROUTED_SUBNETS\" ]; then\n  ROUTED_SUBNETS=\"10.8.1.0/24\"\nfi\n\nfor SUBNET in $ROUTED_SUBNETS; do\n  iptables -t nat -D PREROUTING -s \"$SUBNET\" -p tcp -j REDSOCKS_WARP 2>/dev/null || true\ndone\niptables -t nat -F REDSOCKS_WARP 2>/dev/null || true\niptables -t nat -X REDSOCKS_WARP 2>/dev/null || true\n\nsystemctl stop redsocks-warp 2>/dev/null || true\nsystemctl disable redsocks-warp 2>/dev/null || true\nrm -f /etc/systemd/system/redsocks-warp.service 2>/dev/null || true\nrm -rf /etc/redsocks 2>/dev/null || true\nsystemctl daemon-reload 2>/dev/null || true\n\nwarp-cli --accept-tos disconnect 2>/dev/null || true\nwarp-cli --accept-tos registration delete 2>/dev/null || true\nsystemctl stop warp-svc 2>/dev/null || true\nsystemctl disable warp-svc 2>/dev/null || true\n\napt-get remove -y cloudflare-warp 2>/dev/null || true\napt-get autoremove -y 2>/dev/null || true\n\nrm -rf /var/lib/cloudflare-warp 2>/dev/null || true\nrm -f /etc/apt/sources.list.d/cloudflare-client.list 2>/dev/null || true\nrm -f /usr/share/keyrings/cloudflare-warp-archive-keyring.gpg 2>/dev/null || true\n\necho \"{\"success\":true,\"message\":\"WARP + redsocks removed\"}\"',NULL,'WARP SOCKS5 Proxy: socks5h://127.0.0.1:{{warp_proxy_port}}\nWARP IP: {{warp_ip}}\nMode: {{warp_mode}}\nServer: {{server_host}}',1,1,'2026-10-12 13:07:22','2026-10-13 06:32:09',NULL,'amnezia_compressed',1),(15,'AmneziaWG 3.1','awg31','AmneziaWG 3.1 userspace engine pinned to audited upstream source commits.','{\"engine\": \"builtin_awg\", \"metadata\": {\"interface\": \"awg0\", \"port_range\": [30000, 65000], \"vpn_subnet\": \"10.8.31.0/24\", \"config_file\": \"/opt/amnezia/awg/awg0.conf\", \"tools_commit\": \"ee0f0a9aa34ff0a0da4b3433b9512781cfe02843\", \"container_name\": \"amnezia-awg31\", \"runtime_commit\": \"b5928efb6ca19f0153958460c3d141f04abc5c2e\", \"host_config_dir\": \"/opt/amnezia/awg31\", \"host_config_file\": \"/opt/amnezia/awg31/awg0.conf\", \"container_config_dir\": \"/opt/amnezia/awg\"}}','#!/bin/bash\nset -euo pipefail\nmissing=\"\"\ncommand -v git >/dev/null 2>&1 || missing=\"$missing git\"\ncommand -v ss >/dev/null 2>&1 || missing=\"$missing iproute2\"\nif [ -n \"$missing\" ]; then\n  command -v apt-get >/dev/null 2>&1 || { echo \"AWG31 prerequisites missing:$missing (install git and iproute2)\" >&2; exit 41; }\n  DEBIAN_FRONTEND=noninteractive apt-get update >/dev/null\n  DEBIAN_FRONTEND=noninteractive apt-get install -y git iproute2 >/dev/null\nfi\ncommand -v git >/dev/null 2>&1 && command -v ss >/dev/null 2>&1 || { echo \"AWG31 prerequisites unavailable after install: git iproute2\" >&2; exit 41; }\nROOT=/opt/amnezia/awg31\nSRC=\"$ROOT/src\"\nENGINE_COMMIT=b5928efb6ca19f0153958460c3d141f04abc5c2e\nTOOLS_COMMIT=ee0f0a9aa34ff0a0da4b3433b9512781cfe02843\nCONTAINER_NAME=amnezia-awg31\nIMAGE_NAME=amnezia-awg31\nVPN_PORT=\"${SERVER_PORT:?SERVER_PORT is required}\"\nmkdir -p \"$ROOT\"\nif [ -f \"$ROOT/awg0.conf\" ]; then\n  EXISTING_PORT=$(sed -n \"s/^[[:space:]]*ListenPort[[:space:]]*=[[:space:]]*//p\" \"$ROOT/awg0.conf\" | head -1)\n  printf \"%s\" \"$EXISTING_PORT\" | grep -Eq \"^[0-9]+$\" || { echo \"Invalid existing AWG31 ListenPort\" >&2; exit 44; }\n  VPN_PORT=\"$EXISTING_PORT\"\nfi\nif [ -d \"$SRC/.git\" ]; then\n  test \"$(git -C \"$SRC\" rev-parse HEAD)\" = \"$ENGINE_COMMIT\" || { echo \"provenance failure: existing AWG31 source is at another commit\" >&2; exit 42; }\nelse\n  test ! -e \"$SRC\" || { echo \"provenance failure: source path exists without git metadata\" >&2; exit 42; }\n  git clone https://github.com/amnezia-vpn/amneziawg-go.git \"$SRC\"\n  git -C \"$SRC\" checkout --detach \"$ENGINE_COMMIT\"\nfi\ntest \"$(git -C \"$SRC\" rev-parse HEAD)\" = \"$ENGINE_COMMIT\"\ngit -C \"$SRC\" reset --hard \"$ENGINE_COMMIT\" >/dev/null\ngit -C \"$SRC\" clean -fdx >/dev/null\n# The upstream engine Dockerfile pins a release tag. Replace that build ARG\n# with the adopted immutable tools commit and verify the resulting source.\nsed -i \"s|^ARG AWGTOOLS_COMMIT=.*|ARG AWGTOOLS_COMMIT=$TOOLS_COMMIT|\" \"$SRC/Dockerfile\"\ngrep -Fq \"ARG AWGTOOLS_COMMIT=$TOOLS_COMMIT\" \"$SRC/Dockerfile\"\ntest \"$(git -C \"$SRC\" status --porcelain | head -1)\" = \" M Dockerfile\"\ntest \"$(git -C \"$SRC\" status --porcelain | wc -l)\" -eq 1\nDOCKERFILE_SHA=$(sha256sum \"$SRC/Dockerfile\" | cut -c1-64)\nif ss -lunH | grep -Eq \"[:.]${VPN_PORT}[[:space:]]\"; then\n  docker inspect \"$CONTAINER_NAME\" >/dev/null 2>&1 || { echo \"UDP port already occupied\" >&2; exit 43; }\nfi\ndocker build --pull=false --label \"org.opencontainers.image.revision=$ENGINE_COMMIT\" --label \"io.amnezia.awgtools.revision=$TOOLS_COMMIT\" --label \"io.amnezia.awg31.dockerfile-sha256=$DOCKERFILE_SHA\" -t \"$IMAGE_NAME\" \"$SRC\"\nif [ -f \"$ROOT/awg0.conf\" ]; then\n  test \"$(git -C \"$SRC\" rev-parse HEAD)\" = \"$ENGINE_COMMIT\"\nelse\n  PRIVATE_KEY=$(docker run --rm \"$IMAGE_NAME\" wg genkey)\n  PUBLIC_KEY=$(printf \"%s\" \"$PRIVATE_KEY\" | docker run --rm -i \"$IMAGE_NAME\" wg pubkey)\n  PRESHARED_KEY=$(docker run --rm \"$IMAGE_NAME\" wg genpsk)\n  HEADER_KEY=\"${AWG31_HEADER_PROTECTION_KEY:-$(docker run --rm \"$IMAGE_NAME\" wg genkey)}\"\n  JC=\"${AWG31_JC:-$((4 + RANDOM % 3))}\"\n  JMIN=\"${AWG31_JMIN:-10}\"; JMAX=\"${AWG31_JMAX:-50}\"\n  S1=\"${AWG31_S1:-12}\"; S2=\"${AWG31_S2:-12}\"; S3=\"${AWG31_S3:-12}\"; S4=\"${AWG31_S4:-12}\"\n  H1=\"${AWG31_H1:-1}\"; H2=\"${AWG31_H2:-2}\"; H3=\"${AWG31_H3:-3}\"; H4=\"${AWG31_H4:-4}\"\n  I1=\"${AWG31_I1:-<r 2><b 0x858000010001000000000669636c6f756403636f6d0000010001c00c000100010000105a00044d583737>}\"\n  REKEY_AFTER=\"${AWG31_REKEY_AFTER_TIME:-100-120}\"; REKEY_TIMEOUT=\"${AWG31_REKEY_TIMEOUT:-3-7}\"\n  REJECT_AFTER=\"${AWG31_REJECT_AFTER_TIME:-150-180}\"; KEEPALIVE_TIMEOUT=\"${AWG31_KEEPALIVE_TIMEOUT:-5-15}\"\n  MAX_ATTEMPTS=\"${AWG31_MAX_HANDSHAKE_ATTEMPTS:-15-20}\"\n  RANDOM_TRAILERS=\"${AWG31_RANDOM_TRAILERS:-on}\"; DISABLE_COOKIES=\"${AWG31_DISABLE_COOKIES:-on}\"\n  {\n    echo \"[Interface]\"\n    echo \"PrivateKey = $PRIVATE_KEY\"; echo \"Address = 10.8.31.1/24\"; echo \"ListenPort = $VPN_PORT\"; echo \"MTU = 1280\"\n    echo \"Jc = $JC\"; echo \"Jmin = $JMIN\"; echo \"Jmax = $JMAX\"\n    echo \"S1 = $S1\"; echo \"S2 = $S2\"; echo \"S3 = $S3\"; echo \"S4 = $S4\"\n    echo \"H1 = $H1\"; echo \"H2 = $H2\"; echo \"H3 = $H3\"; echo \"H4 = $H4\"\n    echo \"I1 = $I1\"\n    for n in 2 3 4 5; do v=$(printenv \"AWG31_I$n\" 2>/dev/null || true); test -z \"$v\" || echo \"I$n = $v\"; done\n    echo \"HeaderProtectionKey = $HEADER_KEY\"\n    test -z \"${AWG31_CONTENT_PADDING_ADDITION:-}\" || echo \"ContentPaddingAddition = $AWG31_CONTENT_PADDING_ADDITION\"\n    echo \"RekeyAfterTime = $REKEY_AFTER\"; echo \"RekeyTimeout = $REKEY_TIMEOUT\"; echo \"RejectAfterTime = $REJECT_AFTER\"\n    echo \"KeepaliveTimeout = $KEEPALIVE_TIMEOUT\"; echo \"MaxHandshakeAttempts = $MAX_ATTEMPTS\"\n    echo \"RandomTrailers = $RANDOM_TRAILERS\"; echo \"DisableCookies = $DISABLE_COOKIES\"\n    echo \"PostUp = iptables -A FORWARD -i %i -j ACCEPT; iptables -A FORWARD -o %i -j ACCEPT; iptables -t nat -A POSTROUTING -s 10.8.31.0/24 -o eth0 -j MASQUERADE\"\n    echo \"PostDown = iptables -D FORWARD -i %i -j ACCEPT; iptables -D FORWARD -o %i -j ACCEPT; iptables -t nat -D POSTROUTING -s 10.8.31.0/24 -o eth0 -j MASQUERADE\"\n  } > \"$ROOT/awg0.conf\"\n  printf \"%s\n\" \"$PRIVATE_KEY\" > \"$ROOT/wireguard_server_private_key.key\"\n  printf \"%s\n\" \"$PUBLIC_KEY\" > \"$ROOT/wireguard_server_public_key.key\"\n  printf \"%s\n\" \"$PRESHARED_KEY\" > \"$ROOT/wireguard_psk.key\"\n  printf \"[]\n\" > \"$ROOT/clientsTable\"\n  chmod 600 \"$ROOT\"/*.key \"$ROOT/awg0.conf\"\nfi\ncat > \"$ROOT/start-userspace.sh\" <<\"START_AWG31\"\n#!/bin/sh\nset -eu\namneziawg-go -f awg0 &\nengine_pid=$!\ntrap \"kill $engine_pid 2>/dev/null || true\" EXIT INT TERM\ni=0\nuntil ip link show awg0 >/dev/null 2>&1; do i=$((i+1)); test \"$i\" -lt 50 || exit 1; sleep 0.1; done\nawg-quick strip /opt/amnezia/awg/awg0.conf > /tmp/awg0.setconf\nawg setconf awg0 /tmp/awg0.setconf\nip address replace 10.8.31.1/24 dev awg0\nip link set mtu 1280 up dev awg0\niptables -C FORWARD -i awg0 -j ACCEPT 2>/dev/null || iptables -A FORWARD -i awg0 -j ACCEPT\niptables -C FORWARD -o awg0 -j ACCEPT 2>/dev/null || iptables -A FORWARD -o awg0 -j ACCEPT\niptables -t nat -C POSTROUTING -s 10.8.31.0/24 -o eth0 -j MASQUERADE 2>/dev/null || iptables -t nat -A POSTROUTING -s 10.8.31.0/24 -o eth0 -j MASQUERADE\nwait \"$engine_pid\"\nSTART_AWG31\nchmod 700 \"$ROOT/start-userspace.sh\"\nPUBLIC_KEY=$(cat \"$ROOT/wireguard_server_public_key.key\")\nPRESHARED_KEY=$(cat \"$ROOT/wireguard_psk.key\")\ndocker rm -f \"$CONTAINER_NAME\" >/dev/null 2>&1 || true\ndocker run -d --name \"$CONTAINER_NAME\" --restart unless-stopped --cap-add NET_ADMIN --device /dev/net/tun -p \"${VPN_PORT}:${VPN_PORT}/udp\" -v \"$ROOT:/opt/amnezia/awg:rw\" \"$IMAGE_NAME\" sh /opt/amnezia/awg/start-userspace.sh >/dev/null\nsleep 2\ndocker exec \"$CONTAINER_NAME\" awg show awg0 >/dev/null\ndocker exec \"$CONTAINER_NAME\" pgrep -x amneziawg-go >/dev/null\ndocker top \"$CONTAINER_NAME\" -eo pid,comm,args | grep -F \"amneziawg-go -f awg0\" >/dev/null\nIMAGE_ID=$(docker image inspect \"$IMAGE_NAME\" | grep -m1 \"\\\"Id\\\":\" | cut -d \"\\\"\" -f4)\nprintf \"%s\" \"$IMAGE_ID\" | grep -Eq \"^sha256:[0-9a-f]{64}$\" || { echo \"Invalid AWG31 image identity\" >&2; exit 45; }\nENGINE_BINARY_SHA=$(docker exec \"$CONTAINER_NAME\" sha256sum /usr/bin/amneziawg-go | cut -c1-64)\nTOOLS_BINARY_SHA=$(docker exec \"$CONTAINER_NAME\" sha256sum /usr/bin/awg | cut -c1-64)\nprintf \"Success: true\nPort: %s\nContainer Name: %s\nRuntime Commit: %s\nTools Commit: %s\nImage ID: %s\nDockerfile SHA: %s\nEngine Binary SHA: %s\nTools Binary SHA: %s\n\" \"$VPN_PORT\" \"$CONTAINER_NAME\" \"$ENGINE_COMMIT\" \"$TOOLS_COMMIT\" \"$IMAGE_ID\" \"$DOCKERFILE_SHA\" \"$ENGINE_BINARY_SHA\" \"$TOOLS_BINARY_SHA\"\nprintf \"Server Public Key: %s\nPresharedKey = %s\n\" \"$PUBLIC_KEY\" \"$PRESHARED_KEY\"\nfor field in Jc Jmin Jmax S1 S2 S3 S4 H1 H2 H3 H4 I1 I2 I3 I4 I5 HeaderProtectionKey ContentPaddingAddition RekeyAfterTime RekeyTimeout RejectAfterTime KeepaliveTimeout MaxHandshakeAttempts RandomTrailers DisableCookies; do\n  value=$(sed -n \"s/^[[:space:]]*$field[[:space:]]*=[[:space:]]*//p\" \"$ROOT/awg0.conf\" | head -1)\n  test -z \"$value\" || printf \"%s: %s\n\" \"$field\" \"$value\"\ndone\n','#!/bin/bash\nset -euo pipefail\ndocker rm -f amnezia-awg31 >/dev/null 2>&1 || true\ndocker image rm amnezia-awg31 >/dev/null 2>&1 || true\nrm -rf /opt/amnezia/awg31\nprintf \"{\"success\":true,\"message\":\"AWG31 isolated resources removed\"}\n\"',NULL,'[Interface]\nAddress = {{client_ip}}/32\nDNS = {{dns_servers}}\nPrivateKey = {{private_key}}\nJc = {{Jc}}\nJmin = {{Jmin}}\nJmax = {{Jmax}}\nS1 = {{S1}}\nS2 = {{S2}}\nS3 = {{S3}}\nS4 = {{S4}}\nH1 = {{H1}}\nH2 = {{H2}}\nH3 = {{H3}}\nH4 = {{H4}}\nI1 = {{I1}}\nI2 = {{I2}}\nI3 = {{I3}}\nI4 = {{I4}}\nI5 = {{I5}}\nHeaderProtectionKey = {{HeaderProtectionKey}}\nContentPaddingAddition = {{ContentPaddingAddition}}\nRekeyAfterTime = {{RekeyAfterTime}}\nRekeyTimeout = {{RekeyTimeout}}\nRejectAfterTime = {{RejectAfterTime}}\nKeepaliveTimeout = {{KeepaliveTimeout}}\nMaxHandshakeAttempts = {{MaxHandshakeAttempts}}\nRandomTrailers = {{RandomTrailers}}\nDisableCookies = {{DisableCookies}}\n\n[Peer]\nPublicKey = {{server_public_key}}\nPresharedKey = {{preshared_key}}\nAllowedIPs = 0.0.0.0/0, ::/0\nEndpoint = {{server_host}}:{{server_port}}\nPersistentKeepalive = 25-35',1,1,'2026-10-12 13:07:24','2026-10-13 06:32:10',NULL,'amnezia_compressed',0);
