--
-- Table structure for table `vpn_clients`
--

DROP TABLE IF EXISTS `vpn_clients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vpn_clients` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `server_id` int unsigned NOT NULL,
  `user_id` int unsigned NOT NULL,
  `protocol_id` int unsigned DEFAULT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `client_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `public_key` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `private_key` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `preshared_key` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Full WireGuard config file',
  `qr_code` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Base64 encoded QR code image',
  `bytes_sent` bigint unsigned DEFAULT '0' COMMENT 'Total bytes sent by client',
  `bytes_received` bigint unsigned DEFAULT '0' COMMENT 'Total bytes received by client',
  `aivpn_raw_bytes_in` bigint unsigned NOT NULL DEFAULT '0',
  `aivpn_raw_bytes_out` bigint unsigned NOT NULL DEFAULT '0',
  `aivpn_offset_bytes_in` bigint unsigned NOT NULL DEFAULT '0',
  `aivpn_offset_bytes_out` bigint unsigned NOT NULL DEFAULT '0',
  `last_handshake` timestamp NULL DEFAULT NULL COMMENT 'Last successful WireGuard handshake',
  `last_sync_at` timestamp NULL DEFAULT NULL COMMENT 'Last time stats were synced from server',
  `status` enum('active','disabled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `expires_at` timestamp NULL DEFAULT NULL COMMENT 'Client expiration date (NULL = never expires)',
  `traffic_limit` bigint unsigned DEFAULT NULL COMMENT 'Traffic limit in bytes (NULL = unlimited)',
  `current_speed` bigint DEFAULT '0',
  `speed_up` bigint DEFAULT '0',
  `speed_down` bigint DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_server_client_ip` (`server_id`,`client_ip`),
  KEY `idx_server_id` (`server_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_status` (`status`),
  KEY `idx_expires_at` (`expires_at`),
  KEY `idx_last_handshake` (`last_handshake`),
  KEY `idx_traffic_limit` (`traffic_limit`),
  KEY `idx_protocol_id` (`protocol_id`),
  CONSTRAINT `fk_vpn_clients_protocol` FOREIGN KEY (`protocol_id`) REFERENCES `protocols` (`id`) ON DELETE SET NULL,
  CONSTRAINT `vpn_clients_ibfk_1` FOREIGN KEY (`server_id`) REFERENCES `vpn_servers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vpn_clients_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

